# 文書の純粋参照記法。実装/module/APIではなく、型検査済みの明示引数だけを扱う。
# clone/json_text/same/json_kind/number は下記言語契約の汎用JSON演算。

def present(field):
    return field['tag'] == 'provided'

def known(field):
    return present(field) and field['value'] != 'unknown'

def collection_known(field):
    return (present(field) and json_kind(field['value']) == 'array') or (field['tag'] == 'empty' and field['empty_kind'] == 'empty_list')

def field_locator(field):
    if field['source_ref_id'] is None or field['parent_node_locator'] is None:
        return None
    pointer = field['parent_node_locator']['json_pointer'] + '/' + field['member_name'].replace('~', '~0').replace('/', '~1')
    return {'source_ref_id': clone(field['source_ref_id']), 'json_pointer': pointer}

def values(field):
    if field['tag'] == 'provided':
        return field['value']
    return []

def state_value(field):
    result = {'tag': field['tag']}
    if field['tag'] == 'provided':
        result['value'] = clone(field['value'])
    if field['tag'] == 'empty':
        result['empty_kind'] = field['empty_kind']
    return result

def derived(template, member, value, available):
    field = {'tag': 'absent', 'source_ref_id': clone(template['source_ref_id']), 'parent_node_locator': clone(template['parent_node_locator']), 'member_name': member, 'origin': 'derived_result'}
    if available:
        if value is None:
            field['tag'] = 'explicit_null'
        elif same(value, ''):
            field['tag'] = 'empty'
            field['empty_kind'] = 'empty_string'
        elif same(value, []):
            field['tag'] = 'empty'
            field['empty_kind'] = 'empty_list'
        elif same(value, {}):
            field['tag'] = 'empty'
            field['empty_kind'] = 'empty_object'
        else:
            field['tag'] = 'provided'
            field['value'] = clone(value)
    return field

def observed(field):
    kind = derived(field, 'json_kind', None, False)
    raw = derived(field, 'raw_json_utf8', None, False)
    if field['tag'] == 'provided':
        kind = derived(field, 'json_kind', json_kind(field['value']), True)
        raw = derived(field, 'raw_json_utf8', json_text(field['value']), True)
    elif field['tag'] == 'explicit_null':
        kind = derived(field, 'json_kind', 'null', True)
        raw = derived(field, 'raw_json_utf8', 'null', True)
    elif field['tag'] == 'empty':
        kinds = {'empty_string': 'string', 'empty_list': 'array', 'empty_object': 'object'}
        texts = {'empty_string': '""', 'empty_list': '[]', 'empty_object': '{}'}
        kind = derived(field, 'json_kind', kinds[field['empty_kind']], True)
        raw = derived(field, 'raw_json_utf8', texts[field['empty_kind']], True)
    return {'presence': field['tag'], 'json_kind': kind, 'raw_json_utf8': raw, 'source_ref_id': clone(field['source_ref_id']), 'node_locator': field_locator(field)}

def issue(reason, paths, fields, source):
    return {'reason': reason, 'affected_fields': clone(paths), 'source_refs': [clone(source)], 'node_refs': [clone(f['parent_node_locator']) for f in fields if f['parent_node_locator'] is not None], 'return_to_owner_ref': clone(source['owner_ref']), 'observed_values': [observed(f) for f in fields], 'logical_backflow_role_candidates': []}

def field_issue(field, path, source):
    if field['tag'] != 'provided':
        return [issue('missing_evidence', [path], [field], source)]
    if same(field['value'], 'unknown'):
        return [issue('unknown_state', [path], [field], source)]
    return []

def resolve_source_map(source_ref_id, source_map):
    records = [r for r in source_map['records'] if same(r['source_id'], source_ref_id['value'])]
    frame = {'tag': 'provided', 'source_ref_id': None, 'parent_node_locator': None, 'member_name': 'value', 'origin': 'caller_input', 'value': source_ref_id['value']}
    if same(source_ref_id['value'], ''):
        frame = {'tag': 'empty', 'empty_kind': 'empty_string', 'source_ref_id': None, 'parent_node_locator': None, 'member_name': 'value', 'origin': 'caller_input'}
    if len(records) == 1:
        return {'state': 'resolved', 'source': derived(frame, 'source', records[0], True), 'unresolved': []}
    missing = {'reason': 'source_reference_unbound', 'affected_fields': ['SourceRefID.value'], 'source_refs': [], 'node_refs': [], 'return_to_owner_ref': derived(frame, 'return_to_owner_ref', None, False), 'observed_values': [observed(frame)], 'logical_backflow_role_candidates': []}
    return {'state': 'source_reference_unbound', 'source': derived(frame, 'source', None, False), 'unresolved': [missing]}

def partition_by_class(snapshot):
    result = {'partitions': [], 'unresolved': [], 'unpartitioned_entries': [], 'entry_input_state': clone(snapshot['entries'])}
    if snapshot['entries']['tag'] != 'provided':
        if not collection_known(snapshot['entries']):
            result['unresolved'] += field_issue(snapshot['entries'], 'HistorySnapshot.entries', snapshot['source_ref'])
        return result
    axes = ['task_class', 'model_class', 'source_revision', 'evaluation_period', 'scope']
    for index in range(len(snapshot['entries']['value'])):
        entry = snapshot['entries']['value'][index]
        bad = [name for name in ['task_class', 'model_class'] if not known(entry[name])]
        if len(bad) > 0:
            result['unpartitioned_entries'].append(clone(entry))
            for name in bad:
                reason = 'unknown_applicability' if present(entry[name]) else 'missing_evidence'
                result['unresolved'].append(issue(reason, ['HistorySnapshot.entries[' + str(index) + '].' + name], [entry[name]], entry['snapshot_ref']))
        else:
            key = {name: clone(entry[name]) for name in axes}
            matching = [p for p in result['partitions'] if all(same(state_value(p['key'][name]), state_value(key[name])) for name in axes)]
            if len(matching) == 0:
                result['partitions'].append({'key': key, 'entries': [clone(entry)]})
            else:
                matching[0]['entries'].append(clone(entry))
    return result

def bind_evidence(partition, source_map):
    anchor = partition['key']['task_class']
    entries = []
    refs = []
    unresolved = []
    for index in range(len(partition['entries'])):
        entry = partition['entries'][index]
        resolution = resolve_source_map({'value': entry['snapshot_ref']['source_id']}, source_map)
        unresolved += resolution['unresolved']
        if resolution['state'] == 'resolved':
            source = resolution['source']['value']
            refs.append(clone(source))
            entries.append({'entry': clone(entry), 'source_node_refs': [clone(entry['source_node_ref'])], 'evaluation_ref': clone(entry['evaluation_ref']), 'receipt_ref': clone(source['receipt_ref'])})
        if present(entry['assignment_ref']):
            assigned = entry['assignment_ref']['value']
            assignment_resolution = resolve_source_map({'value': assigned['source_id']}, source_map)
            unresolved += assignment_resolution['unresolved']
            if assignment_resolution['state'] == 'resolved':
                refs.append(clone(assignment_resolution['source']['value']))
    body = {'partition_key': clone(partition['key']), 'entries': entries, 'evidence_refs': refs}
    return {'bound': derived(anchor, 'bound', body, len(entries) > 0), 'unresolved': unresolved}

def assessment(entry, state, level, source, node, portion):
    result = {name: clone(entry[name]) for name in ['task_class', 'model_class', 'source_revision', 'evaluation_period', 'scope']}
    result.update({'evaluation_state': state, 'basis_refs': [clone(source)], 'applicability_condition': clone(entry['applicability_condition']) if 'applicability_condition' in entry else derived(entry['scope'], 'applicability_condition', None, False), 'basis_ref': clone(entry['basis_ref']) if 'basis_ref' in entry else derived(entry['scope'], 'basis_ref', None, False), 'level': clone(level), 'unassessed_portion': clone(portion), 'source_node_refs': [clone(node)]})
    return result

def resolve_applicability(group, claims):
    result = {'assessments': [], 'unresolved': []}
    axes = ['task_class', 'model_class', 'source_revision', 'evaluation_period', 'scope']
    matching = [c for c in claims if all(known(c[name]) and known(group['key'][name]) and same(c[name]['value'], group['key'][name]['value']) for name in axes)]
    if len(matching) > 0:
        explicit_levels = [c['level']['value'] for c in matching if known(c['evaluation_state']) and c['evaluation_state']['value'] == 'evaluated' and known(c['level'])]
        conflicting = any(not same(left, right) for left in explicit_levels for right in explicit_levels)
        for claim in matching:
            rendered = render_qualitative(claim)
            if conflicting:
                for row in rendered['assessments']:
                    row['evaluation_state'] = 'unknown'
                    row['level'] = derived(claim['level'], 'level', None, False)
                rendered['unresolved'].append(issue('conflicting_evidence', ['QualitativeClaim.level'], [c['level'] for c in matching], claim['snapshot_ref']))
            result['assessments'] += rendered['assessments']
            result['unresolved'] += rendered['unresolved']
        return result
    for index in range(len(group['entries'])):
        entry = group['entries'][index]
        source = entry['snapshot_ref']
        template = entry['outcome_state']
        state = 'unknown'
        required = ['evaluation_ref', 'source_revision', 'evaluation_period', 'scope']
        for name in required:
            result['unresolved'] += field_issue(entry[name], 'HistoryPartition.entries[' + str(index) + '].' + name, source)
        if known(template) and same(template['value'], 'unassessed'):
            state = 'unassessed'
        elif known(template) and same(template['value'], 'success') and all(known(entry[name]) for name in required):
            state = 'evaluated'
        else:
            result['unresolved'] += field_issue(template, 'HistoryPartition.entries[' + str(index) + '].outcome_state', source)
            if present(template) and not same(template['value'], 'unknown') and not same(template['value'], 'success'):
                result['unresolved'].append(issue('unknown_applicability', ['HistoryPartition.entries[' + str(index) + '].outcome_state'], [template], source))
        result['assessments'].append(assessment(entry, state, derived(template, 'level', None, False), source, entry['source_node_ref'], derived(template, 'unassessed_portion', None, False)))
    return result



def field_semantics(field):
    if field['tag'] == 'provided':
        return ['provided', field['value']]
    if field['tag'] == 'empty':
        return ['empty', field['empty_kind']]
    return [field['tag']]

def id_set_semantics(field):
    if field['tag'] == 'provided' and json_kind(field['value']) == 'array':
        members = {}
        for identity in field['value']:
            members[identity] = True
        return json_text(['known_set', json_text(members)])
    if field['tag'] == 'empty' and field['empty_kind'] == 'empty_list':
        return json_text(['known_set', json_text({})])
    return field_semantics(field)

def value_binding_semantics(bindings):
    by_position_id = {}
    for binding in bindings:
        value = binding['value']
        locator = field_locator(value)
        locator_value = None if locator is None else [locator['source_ref_id']['value'], locator['json_pointer']]
        record = [field_semantics(value), locator_value]
        position_id = binding['position_id']
        if position_id in by_position_id:
            by_position_id[position_id].append(record)
        else:
            by_position_id[position_id] = [record]
    return {'binding_count': len(bindings), 'by_position_id': by_position_id}

def same_value_bindings(source_bindings, caller_bindings):
    if len(source_bindings) != len(caller_bindings):
        return False
    matched = [False for _ in range(len(caller_bindings))]
    for source_binding in source_bindings:
        source_value = source_binding['value']
        source_locator = field_locator(source_value)
        source_locator_value = None if source_locator is None else [source_locator['source_ref_id']['value'], source_locator['json_pointer']]
        found = False
        for index in range(len(caller_bindings)):
            if not matched[index] and not found:
                caller_binding = caller_bindings[index]
                caller_value = caller_binding['value']
                caller_locator = field_locator(caller_value)
                caller_locator_value = None if caller_locator is None else [caller_locator['source_ref_id']['value'], caller_locator['json_pointer']]
                if source_binding['position_id'] == caller_binding['position_id'] and same(field_semantics(source_value), field_semantics(caller_value)) and same(source_locator_value, caller_locator_value):
                    matched[index] = True
                    found = True
        if not found:
            return False
    return all(matched)



def position_reason_semantics(field):
    if field['tag'] != 'provided':
        return field_semantics(field)
    by_position_id = {}
    for item in field['value']:
        record = {'field': field_semantics(item['reason']), 'locator': field_locator(item['reason'])}
        position_id = item['position_id']
        if position_id in by_position_id:
            by_position_id[position_id].append(record)
        else:
            by_position_id[position_id] = [record]
    return {'tag': 'provided', 'by_position_id': by_position_id, 'count': len(field['value'])}

def operation_differences(source_operation, caller_operation):
    differences = []
    if not same(source_operation['operation_kind'], caller_operation['operation_kind']):
        differences.append('operation_kind')
        return differences
    if not same(source_operation['source_definition_locator'], caller_operation['source_definition_locator']):
        differences.append('source_definition_locator')
    if not same(field_semantics(source_operation['source_rule_revision']), field_semantics(caller_operation['source_rule_revision'])):
        differences.append('source_rule_revision')
    if not same(id_set_semantics(source_operation['eligible_position_ids']), id_set_semantics(caller_operation['eligible_position_ids'])):
        differences.append('eligible_position_ids')
    if caller_operation['operation_kind'] == 'count_ratio':
        for name in ['numerator_position_ids', 'denominator_position_ids']:
            if not same(id_set_semantics(source_operation[name]), id_set_semantics(caller_operation[name])):
                differences.append(name)
        if not same(source_operation['numerator_conditions'], caller_operation['numerator_conditions']):
            differences.append('numerator_conditions')
    elif caller_operation['operation_kind'] == 'arithmetic_mean':
        if not same(id_set_semantics(source_operation['mean_position_ids']), id_set_semantics(caller_operation['mean_position_ids'])):
            differences.append('mean_position_ids')
        if not same_value_bindings(source_operation['value_bindings'], caller_operation['value_bindings']):
            differences.append('value_bindings')
    if not same(field_semantics(source_operation['exclusion_allowed']), field_semantics(caller_operation['exclusion_allowed'])):
        differences.append('exclusion_allowed')
    if not same(position_reason_semantics(source_operation['denominator_exclusion_reasons']), position_reason_semantics(caller_operation['denominator_exclusion_reasons'])):
        differences.append('denominator_exclusion_reasons')
    return differences




def finish_metric_source_findings(result, findings):
    for finding in findings:
        duplicate = False
        if finding['reason'] == 'conflicting_evidence':
            for existing in result['unresolved']:
                if same(existing, finding):
                    duplicate = True
        if not duplicate:
            result['unresolved'].append(finding)
    return result

def reconstruct_metric(claim, source_definition_input, operation_input):
    source = claim['snapshot_ref']
    result = {'summary': derived(claim['scope'], 'summary', None, False), 'unresolved': []}
    source_findings = []
    for name in ['scope', 'positions', 'rule_scorer']:
        result['unresolved'] += field_issue(claim[name], 'MetricClaim.' + name, source)
    if not present(claim['rule_scorer']):
        return finish_metric_source_findings(result, source_findings)
    rule = claim['rule_scorer']['value']
    for name in ['rule_revision', 'scorer_oracle_revision', 'calculation_definition']:
        result['unresolved'] += field_issue(rule[name], 'MetricClaim.rule_scorer.' + name, source)
    source_definition = None
    source_operation = None
    if source_definition_input['tag'] != 'provided':
        source_findings.append(issue('rule_not_supplied', ['SourceCalculationDefinition'], [source_definition_input], source))
    else:
        source_definition = source_definition_input['value']
        if source_definition['binding_state'] == 'unknown':
            source_findings.append(issue('unknown_state', ['SourceCalculationDefinition.binding_state'], [source_definition_input], source))
        else:
            source_operation_field = source_definition['operation']
            if source_operation_field['tag'] != 'provided':
                source_findings.append(issue('rule_not_supplied', ['SourceCalculationDefinition.operation'], [source_definition_input], source))
            else:
                source_operation = source_operation_field['value']
    if operation_input['tag'] != 'provided':
        result['unresolved'].append(issue('rule_not_supplied', ['MetricOperationInput'], [operation_input], source))
        return finish_metric_source_findings(result, source_findings)
    op = operation_input['value']
    source_differences = []
    if source_definition is not None and not same(source_definition['source_definition_locator'], field_locator(rule['calculation_definition'])):
        source_differences.append('source_definition_locator')
    if source_definition is not None and not same(field_semantics(source_definition['source_rule_revision']), field_semantics(rule['rule_revision'])):
        source_differences.append('source_rule_revision')
    if source_operation is not None:
        if not same(source_definition['source_definition_locator'], source_operation['source_definition_locator']):
            source_differences.append('source_definition_locator')
        if not same(field_semantics(source_definition['source_rule_revision']), field_semantics(source_operation['source_rule_revision'])):
            source_differences.append('source_rule_revision')
        source_differences.extend(['operation.' + name for name in operation_differences(source_operation, op)])
    if len(source_differences) > 0:
        paths = []
        for name in source_differences:
            source_path = 'SourceCalculationDefinition.' + name
            if name.startswith('operation.'):
                source_path = 'SourceCalculationDefinition.' + name
                caller_name = name[len('operation.'): ]
            else:
                caller_name = name
            paths.extend([source_path, 'MetricOperationInput.' + caller_name])
        source_findings.append(issue('conflicting_evidence', paths, [source_definition_input, operation_input], source))
    if op['operation_kind'] == 'unsupported':
        result['unresolved'].append(issue('rule_not_supplied', ['MetricOperationInput.operation_kind'], [operation_input], source))
        return finish_metric_source_findings(result, source_findings)
    if field_locator(rule['calculation_definition']) is None:
        result['unresolved'].append(issue('source_reference_unbound', ['MetricClaim.rule_scorer.calculation_definition'], [rule['calculation_definition']], source))
        return finish_metric_source_findings(result, source_findings)
    if not same(op['source_definition_locator'], field_locator(rule['calculation_definition'])) or not same(state_value(op['source_rule_revision']), state_value(rule['rule_revision'])):
        result['unresolved'].append(issue('conflicting_evidence', ['MetricOperationInput.source_definition_locator', 'MetricOperationInput.source_rule_revision'], [operation_input, rule['calculation_definition'], rule['rule_revision']], source))
    if known(rule['applicability_scope']) and known(claim['scope']) and not same(rule['applicability_scope']['value'], claim['scope']['value']):
        result['unresolved'].append(issue('conflicting_evidence', ['MetricClaim.rule_scorer.applicability_scope', 'MetricClaim.scope'], [rule['applicability_scope'], claim['scope']], source))
    if len(result['unresolved']) > 0:
        return finish_metric_source_findings(result, source_findings)
    if not collection_known(op['eligible_position_ids']):
        result['unresolved'] += field_issue(op['eligible_position_ids'], 'MetricOperationInput.eligible_position_ids', source)
        return finish_metric_source_findings(result, source_findings)
    eligible = values(op['eligible_position_ids'])
    positions = values(claim['positions'])
    ids = [p['position_id']['value'] for p in positions if present(p['position_id'])]
    if len(ids) != len(positions) or len(set(ids)) != len(ids) or len(set(eligible)) != len(eligible) or any(identity not in ids for identity in eligible) or len(eligible) == 0:
        result['unresolved'].append(issue('eligible_set_mismatch', ['MetricOperationInput.eligible_position_ids', 'MetricClaim.positions'], [op['eligible_position_ids'], claim['positions']], source))
        return finish_metric_source_findings(result, source_findings)
    if present(claim['eligible_position_ids']) and set(claim['eligible_position_ids']['value']) != set(eligible):
        result['unresolved'].append(issue('eligible_set_mismatch', ['MetricClaim.eligible_position_ids', 'MetricOperationInput.eligible_position_ids'], [claim['eligible_position_ids'], op['eligible_position_ids']], source))
        return finish_metric_source_findings(result, source_findings)
    by_id = {p['position_id']['value']: p for p in positions}
    selected_field = op['denominator_position_ids'] if op['operation_kind'] == 'count_ratio' else op['mean_position_ids']
    selected_path = 'MetricOperationInput.denominator_position_ids' if op['operation_kind'] == 'count_ratio' else 'MetricOperationInput.mean_position_ids'
    if not collection_known(selected_field):
        result['unresolved'] += field_issue(selected_field, selected_path, source)
        return finish_metric_source_findings(result, source_findings)
    selected = values(selected_field)
    if len(selected) == 0 or len(selected) != len(set(selected)) or any(identity not in eligible for identity in selected):
        result['unresolved'].append(issue('eligible_set_mismatch', [selected_path], [selected_field], source))
        return finish_metric_source_findings(result, source_findings)
    if present(rule['eligible_position_ids']) and set(rule['eligible_position_ids']['value']) != set(eligible):
        result['unresolved'].append(issue('eligible_set_mismatch', ['MetricClaim.rule_scorer.eligible_position_ids', 'MetricOperationInput.eligible_position_ids'], [rule['eligible_position_ids'], op['eligible_position_ids']], source))
    for index in range(len(positions)):
        position = positions[index]
        if position['position_id']['value'] in eligible and present(position['eligible']) and position['eligible']['value'] is False:
            result['unresolved'].append(issue('eligible_set_mismatch', ['MetricClaim.positions[' + str(index) + '].eligible', 'MetricOperationInput.eligible_position_ids'], [position['eligible'], op['eligible_position_ids']], source))
    if len(result['unresolved']) > 0:
        return finish_metric_source_findings(result, source_findings)
    excluded_from_denominator = [identity for identity in eligible if identity not in selected]
    denominator_reason_field = op['denominator_exclusion_reasons']
    denominator_exclusion_values = values(denominator_reason_field) if collection_known(denominator_reason_field) else []
    denominator_exclusion_ids = [item['position_id'] for item in denominator_exclusion_values]
    if len(excluded_from_denominator) > 0:
        if not known(op['exclusion_allowed']) or op['exclusion_allowed']['value'] is not True:
            result['unresolved'].append(issue('eligible_set_mismatch', [selected_path, 'MetricOperationInput.exclusion_allowed'], [selected_field, op['exclusion_allowed']], source))
        if not collection_known(denominator_reason_field):
            result['unresolved'] += field_issue(denominator_reason_field, 'MetricOperationInput.denominator_exclusion_reasons', source)
        elif len(denominator_exclusion_ids) != len(set(denominator_exclusion_ids)) or set(denominator_exclusion_ids) != set(excluded_from_denominator):
            result['unresolved'].append(issue('eligible_set_mismatch', ['MetricOperationInput.denominator_exclusion_reasons', selected_path], [denominator_reason_field, selected_field], source))
        else:
            for exclusion in denominator_exclusion_values:
                if not known(exclusion['reason']):
                    result['unresolved'] += field_issue(exclusion['reason'], 'MetricOperationInput.denominator_exclusion_reasons[' + exclusion['position_id'] + '].reason', source)
    elif denominator_reason_field['tag'] == 'provided' and not collection_known(denominator_reason_field):
        result['unresolved'].append(issue('eligible_set_mismatch', ['MetricOperationInput.denominator_exclusion_reasons', selected_path], [denominator_reason_field, selected_field], source))
    elif collection_known(denominator_reason_field) and len(denominator_exclusion_ids) > 0:
        result['unresolved'].append(issue('eligible_set_mismatch', ['MetricOperationInput.denominator_exclusion_reasons', selected_path], [denominator_reason_field, selected_field], source))
    elif denominator_reason_field['tag'] not in ['absent', 'empty']:
        result['unresolved'] += field_issue(denominator_reason_field, 'MetricOperationInput.denominator_exclusion_reasons', source)
    elif denominator_reason_field['tag'] == 'empty' and denominator_reason_field['empty_kind'] != 'empty_list':
        result['unresolved'] += field_issue(denominator_reason_field, 'MetricOperationInput.denominator_exclusion_reasons', source)
    if len(result['unresolved']) > 0:
        return finish_metric_source_findings(result, source_findings)
    if op['operation_kind'] == 'count_ratio':
        if not collection_known(op['numerator_position_ids']):
            result['unresolved'] += field_issue(op['numerator_position_ids'], 'MetricOperationInput.numerator_position_ids', source)
            return finish_metric_source_findings(result, source_findings)
        numerator = values(op['numerator_position_ids'])
        if len(numerator) != len(set(numerator)) or any(identity not in selected for identity in numerator):
            result['unresolved'].append(issue('eligible_set_mismatch', ['MetricOperationInput.numerator_position_ids'], [op['numerator_position_ids']], source))
