def classifier_walk(value, typename, path, source, types, selected):
    result = []
    if typename.startswith('FieldValue<'):
        inner = typename[11:-1]
        if selected and not (path == 'HistorySnapshot.entries' and value['tag'] == 'empty' and value['empty_kind'] == 'empty_list'):
            result += field_issue(value, path, source)
        if present(value):
            result += classifier_walk(value['value'], inner, path, source, types, False)
        return result
    if typename.startswith('list<'):
        inner = typename[5:-1]
        for index in range(len(value)):
            result += classifier_walk(value[index], inner, path + '[' + str(index) + ']', source, types, False)
        return result
    if typename not in types:
        return []
    if typename in ['SourceRef', 'SourceRefID', 'NodeLocator', 'FieldValue', 'MetricCalculationOperation']:
        return []
    if 'source_ref' in value and typename == 'HistorySnapshot':
        source = value['source_ref']
    if 'snapshot_ref' in value:
        source = value['snapshot_ref']
    profiles = {'HistorySnapshot': ['entries'], 'HistoryEntry': ['outcome_state', 'evaluation_ref', 'source_revision', 'evaluation_period', 'scope'], 'MetricClaim': ['scope', 'positions', 'rule_scorer'], 'MetricPosition': ['outcome_state', 'disposition'], 'RuleScorer': ['rule_revision', 'scorer_oracle_revision', 'applicability_scope', 'calculation_definition']}
    for field in types[typename]['fields']:
        name = field['name']
        result += classifier_walk(value[name], field['type'], path + '.' + name, source, types, name in profiles.get(typename, []))
    return result

def classify_unknown(snapshot):
    if 'entries' in snapshot:
        return classifier_walk(snapshot, 'HistorySnapshot', 'HistorySnapshot', snapshot['source_ref'], TYPE_DEFINITIONS, False)
    return classifier_walk(snapshot, 'MetricClaim', 'MetricClaim', snapshot['snapshot_ref'], TYPE_DEFINITIONS, False)

def render_qualitative(claim):
    source = claim['snapshot_ref']
    unresolved = []
    required = ['scope', 'applicability_condition', 'basis_ref']
    for name in required:
        unresolved += field_issue(claim[name], 'QualitativeClaim.' + name, source)
    explicit = claim['evaluation_state']
    state = 'unknown'
    raw_fields = [explicit, claim['level'], claim['applicability_condition'], claim['basis_ref'], claim['unassessed_portion']]
    if explicit['tag'] != 'provided':
        unresolved.append(issue('missing_evidence', ['QualitativeClaim.evaluation_state'], raw_fields, source))
    elif explicit['value'] in ['evaluated', 'unassessed', 'unknown']:
        state = explicit['value']
        if state == 'unknown':
            unresolved.append(issue('unknown_state', ['QualitativeClaim.evaluation_state'], raw_fields, source))
    else:
        unresolved.append(issue('unknown_state', ['QualitativeClaim.evaluation_state'], raw_fields, source))
    valid = all(known(claim[name]) for name in required)
    if not valid:
        state = 'unknown'
    if valid and state == 'evaluated':
        level = clone(claim['level'])
        unresolved += field_issue(level, 'QualitativeClaim.level', source)
    else:
        level = derived(claim['level'], 'level', None, False)
        if state == 'unassessed' and present(claim['level']):
            unresolved.append(issue('unknown_applicability', ['QualitativeClaim.level'], raw_fields, source))
        elif not valid and len(unresolved) > 0:
            unresolved[0]['observed_values'].append(observed(claim['level']))
    row = assessment(claim, state, level, source, claim['source_node_ref'], claim['unassessed_portion'])
    return {'assessments': [row], 'metric_summaries': [], 'failure_observations': [], 'unresolved': unresolved, 'existing_assignment_refs': derived(claim['level'], 'existing_assignment_refs', None, False), 'authority_effect': 'none'}

def assemble_evaluation_material(input):
    result = {'assessments': [], 'metric_summaries': [], 'failure_observations': [], 'unresolved': [], 'existing_assignment_refs': clone(input['existing_assignment_refs']), 'authority_effect': 'none'}
    for values_ in [input['applicability_results'], input['metric_renderings'], input['qualitative_renderings']]:
        for item in values_:
            result['assessments'] += clone(item['assessments'])
    for values_ in [input['metric_renderings'], input['qualitative_renderings']]:
        for item in values_:
            result['metric_summaries'] += clone(item['metric_summaries'])
    for item in input['metric_renderings']:
        result['failure_observations'] += clone(item['failure_observations'])
    for values_ in [input['partitions'], input['bindings'], input['applicability_results'], input['metric_renderings'], input['qualitative_renderings']]:
        for item in values_:
            result['unresolved'] += clone(item['unresolved'])
    result['unresolved'] += clone(input['unknown_results'])
    for item in result['unresolved']:
        item['logical_backflow_role_candidates'] += clone(input['logical_backflow_role_candidates'])
    return result
